{"answer": "find experiment -type f \( -name "*.txt" -o -name "*.csv" -o -name "*.log" \) -print0 | xargs -0 -I{} sh -c 'case "{}" in
  *.txt) idx=0;;
  *.csv) idx=1;;
  *.log) idx=2;;
esac;
cnt=$(grep -E -v "^[[:space:]]*$" "{}" | wc -l);
echo "$idx $cnt"' | awk '{a[$1]+=$2} END{printf "%d %d %d", a[0], a[1], a[2]}'"}

{"script": "running=$(ps -e -o comm | grep -v '^\[' | wc -l);
mem=$(free | awk '/Mem/ {printf("%d", ($3 - $6)*100/$2)}');
disk=$(df / | awk 'NR==2 {gsub("%", "", $5); print $5}');
result=$((running + mem + disk));
echo $result"}

